"""Playable local pets with bounded pathfinding and explicit cosmetic games."""
PET_WORLD_PETS_JS = r"""
(()=>{'use strict';
function attach(renderer,{pets,companionState='idle',reducedMotion=false,seed=1,onChange=()=>{},onFinish=()=>{}}){let stopped=false,selected=pets[0]?.id||'',mode='walk',last=0,game=null,lastFollow=-Infinity;const homes=new Map(pets.map(p=>[p.id,{x:p.x,y:p.y}]));const actors=pets.map(p=>({...p,pose:'idle',direction:'front',path:[],route:null}));let random=Number(seed)||1;const rng=()=>{random=(Math.imul(1664525,random)+1013904223)>>>0;return random/4294967296;};
 function path(from,to){const g=renderer.ground,start=from.y*24+from.x,end=to.y*24+to.x;if(!g.walkable[end]||!g.walkable[start])return null;const q=[start],prev=new Int16Array(576).fill(-2);prev[start]=-1;for(let i=0;i<q.length;i++){const n=q[i];if(n===end)break;for(const [dx,dy] of [[1,0],[-1,0],[0,1],[0,-1]]){const x=n%24+dx,y=Math.floor(n/24)+dy,j=y*24+x;if(x<0||y<0||x>=24||y>=24||prev[j]!==-2||!g.walkable[j]||Math.abs(g.heights[n]-g.heights[j])>1)continue;prev[j]=n;q.push(j);}}if(prev[end]===-2)return null;const result=[];for(let n=end;n!==start;n=prev[n])result.push({x:n%24,y:Math.floor(n/24)});return result.reverse();}
 function position(p){return p.route?{x:p.route.from.x,y:p.route.from.y}:{x:Math.round(p.x),y:Math.round(p.y)};}
 function move(p,to,finish=null,user=false){const route=path(position(p),to);if(!route)return false;if(user)p.reactUntil=0;p.x=Math.round(p.x);p.y=Math.round(p.y);p.route=null;p.path=route;p.finish=finish;if(!route.length){p.finish=null;finish?.();return true;}if(user)onChange();p.pose='tool';if(reducedMotion){p.x=to.x;p.y=to.y;p.path=[];p.finish=null;p.pose='idle';finish?.();}return true;}
 function react(emote){const p=actors.find(p=>p.id===selected);if(!p)return;p.pose=emote;p.reactUntil=performance.now()+1600;window.VoolPetCosmetics?.play(p.id,emote);}
 function setCompanion(state){const p=actors.find(p=>p.id===selected);if(!p)return;if(state===companionState&&(p.workState===state||p.manualState===state))return;companionState=state;if(game)return;p.workState=state;p.manualState='';if(['tool','starting','thinking','waiting','approval'].includes(state)){const desk=renderer.yard.decorations.find(d=>d.id==='desk');if(desk){for(const [dx,dy] of [[0,1],[1,0],[-1,0],[0,-1]])if(move(p,{x:desk.x+dx,y:desk.y+dy},()=>{p.pose=state==='approval'?'wave':'work';}))break;}p.pose=state==='approval'?'wave':'work';}else{p.path=[];p.route=null;p.x=Math.round(p.x);p.y=Math.round(p.y);move(p,homes.get(p.id)||position(p),()=>{p.pose=state==='unknown'?'unknown':'idle';});p.pose=state==='unknown'?'unknown':'idle';}}
 function tick(now){if(stopped)return;if(game?.kind==='race'){const elapsed=now-game.start;for(let i=0;i<actors.length;i++){const p=actors[i],duration=game.durations[p.id]||4000,fraction=reducedMotion?1:Math.min(1,elapsed/duration),index=Math.min(game.path.length-1,Math.floor(fraction*(game.path.length-1)));Object.assign(p,game.path[index]);p.pose=fraction===1?'happy':'spar';}if(reducedMotion||elapsed>=Math.max(...Object.values(game.durations))){game=null;onFinish('race');}}
 else for(const p of actors){if(p.reactUntil&&now<p.reactUntil)continue;if(p.reactUntil){p.reactUntil=0;p.pose=p.workState==='approval'?'wave':['tool','starting','thinking','waiting'].includes(p.workState)?'work':p.workState==='unknown'?'unknown':'idle';}if(p.route){const f=Math.min(1,(now-p.route.start)/300);p.x=p.route.from.x+(p.route.to.x-p.route.from.x)*f;p.y=p.route.from.y+(p.route.to.y-p.route.from.y)*f;p.direction=p.route.to.x<p.route.from.x?'left':p.route.to.x>p.route.from.x?'right':'front';if(f===1)p.route=null;}
 if(!p.route&&p.path.length){const to=p.path.shift();p.route={from:{x:p.x,y:p.y},to,start:now};}else if(!p.route&&!p.path.length&&p.finish){const done=p.finish;p.finish=null;p.pose='idle';done();}
 if(!p.route&&!p.path.length&&!p.finish&&!p.workState&&!reducedMotion&&now-last>2000){const v=rng();if(v<.08){const x=Math.max(0,Math.min(23,Math.round(p.x)+(rng()<.5?-1:1))),y=Math.round(p.y);move(p,{x,y});}else if(v<.13)p.pose='nap';else if(v<.2)p.pose='idle';}}
 if(game?.kind==='dig'&&(reducedMotion||now-game.start>1400)){game=null;react('surprise');onFinish('dig');}if(now-last>2000)last=now;renderer.setPets(actors);renderer.frame(now);}
 const api={tick,path,actors,onClick(id){if(!actors.some(p=>p.id===id))return false;const old=actors.find(p=>p.id===selected);if(old&&old.id!==id){old.workState='';move(old,homes.get(old.id)||position(old));}selected=id;setCompanion(companionState);return true;},follow(to){const p=actors.find(p=>p.id===selected),now=performance.now();if(!p||!to||reducedMotion||game||p.route||p.path.length||now-lastFollow<4000||!['','idle'].includes(p.workState||''))return false;const distance=Math.abs(to.x-p.x)+Math.abs(to.y-p.y);if(distance<1||distance>3)return false;const route=path(position(p),to);if(!route)return false;lastFollow=now;return move(p,route[Math.min(1,route.length-1)]);},get selected(){return selected;},get mode(){return mode;},setMode(value){mode=value;},setCompanion,react,moveTo(to){const p=actors.find(p=>p.id===selected);if(!p||game)return false;p.workState='';p.manualState=companionState;return move(p,to,null,true);},moveBy(dx,dy){const p=actors.find(p=>p.id===selected);return p?api.moveTo({x:Math.round(p.x)+dx,y:Math.round(p.y)+dy}):false;},fetch(to){const p=actors.find(p=>p.id===selected);if(!p||game)return false;const origin=position(p);if(!path(origin,to)||!path(to,origin))return false;game={kind:'fetch'};renderer.setToy(to);p.workState='';p.reactUntil=0;return move(p,to,()=>{renderer.setToy(null);p.carry=true;p.pose='happy';move(p,origin,()=>{p.carry=false;game=null;react('happy');onFinish('fetch');});});},dig(){if(game)return false;const p=actors.find(p=>p.id===selected);if(!p)return false;p.pose='work';game={kind:'dig',start:performance.now()};return true;},startRace(track){if(!track?.path?.length)return false;game={kind:'race',path:track.path,start:performance.now(),durations:Object.fromEntries(actors.map(p=>[p.id,2000+6000*(track.times[p.id]||1)/Math.max(...Object.values(track.times))]))};return true;},serialize(){return actors.map(p=>({id:p.id,x:Math.round(p.x),y:Math.round(p.y)}));},stop(){stopped=true;renderer.setToy(null);for(const p of actors){p.path=[];p.route=null;}game=null;},get game(){return game?.kind||'';}};renderer.setPets(actors);setCompanion(companionState);return api;
}
window.VoolYardPets={attach};})();
"""
